import { DEFINITION, normalizeLabel } from './label.js'

/** One refusal of a definitions file line, carrying the 1-based line it was read at. */
export class DefsError extends Error {
  /**
   * @param {number} line - the 1-based line within the definitions file.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'DefsError'
    this.line = line
  }
}

/**
 * Parse a definitions file's text into a label-to-url map.
 * @param {string} text - the whole file.
 * @returns {Map<string, string>} the normalized label to url.
 * @throws {DefsError} on a line that is neither blank, a comment, nor a definition, or on a label defined twice.
 */
export function parseDefinitions(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  const definitions = new Map()
  for (let index = 0; index < lines.length; index += 1) {
    const trimmed = lines[index].trim()
    const line = index + 1
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const match = DEFINITION.exec(trimmed)
    if (match === null) throw new DefsError(line, 'expected [label]: <url>')
    const label = normalizeLabel(match[1])
    if (definitions.has(label)) throw new DefsError(line, `label ${label} is defined twice`)
    definitions.set(label, match[2])
  }
  return definitions
}
"}

