import { escapeText } from './html.js'
import { renderInline } from './inline.js'
import { DEFINITION, normalizeLabel } from './label.js'

const FENCE = /^(`{3,})([^`]*)$/
const HEADING = /^(#{1,6}) (.*)$/
const ITEM = /^( *)- (.*)$/

/** One refusal of a document line, carrying the 1-based line it was read at. */
export class BlockError extends Error {
  /**
   * @param {number} line - the 1-based input line.
   * @param {string} message - the message the specification words, without the position.
   */
  constructor(line, message) {
    super(message)
    this.name = 'BlockError'
    this.line = line
  }
}

/**
 * Every input line, with the empty tail a trailing newline leaves dropped.
 * @param {string} text - the whole input.
 * @returns {string[]} the lines.
 */
export function splitLines(text) {
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

/**
 * The blocks of one document, and the labels it defines together with any
 * carried in from a definitions file.
 * @param {string[]} lines - the document's lines.
 * @param {Map<string, string>} [priorDefinitions] - labels already in force, keyed by their normalized form.
 * @returns {{blocks: object[], definitions: Map<string, string>}} the blocks in document order and the labels in force.
 * @throws {BlockError} on an unterminated fence or a label defined twice.
 */
export function parse(lines, priorDefinitions = new Map()) {
  const out = []
  let paragraph = []
  let list // the root array of the open list's items, or undefined
  let stack // the chain of item arrays open in the list, stack[0] === list
  const definitions = new Map(priorDefinitions)
  const flush = () => {
    if (paragraph.length > 0) {
      out.push({ kind: 'paragraph', lines: paragraph })
      paragraph = []
    }
    if (list !== undefined) {
      out.push({ kind: 'list', items: list })
      list = undefined
      stack = undefined
    }
  }
  for (let index = 0; index < lines.length; index += 1) {
    const raw = lines[index]
    const line = index + 1
    const fence = FENCE.exec(raw)
    if (fence !== null) {
      flush()
      const content = []
      let close = -1
      for (let scan = index + 1; scan < lines.length; scan += 1) {
        const candidate = lines[scan].trim()
        if (/^`{3,}$/u.test(candidate) && candidate.length >= fence[1].length) {
          close = scan
          break
        }
        content.push(lines[scan])
      }
      if (close === -1) throw new BlockError(line, 'unterminated code fence')
      out.push({ kind: 'fence', info: fence[2].trim().split(/\s+/u)[0], content })
      index = close
      continue
    }
    const trimmed = raw.trim()
    if (trimmed === '') {
      flush()
      continue
    }
    const definition = DEFINITION.exec(trimmed)
    if (definition !== null) {
      flush()
      const label = normalizeLabel(definition[1])
      if (definitions.has(label)) throw new BlockError(line, `label ${label} is defined twice`)
      definitions.set(label, definition[2])
      continue
    }
    const heading = HEADING.exec(raw)
    if (heading !== null) {
      flush()
      out.push({ kind: 'heading', level: heading[1].length, text: heading[2].trim() })
      continue
    }
    const item = ITEM.exec(raw)
    if (item !== null && paragraph.length === 0) {
      if (list === undefined) {
        list = []
        stack = [list]
      }
      const level = Math.min(Math.floor(item[1].length / 2), stack.length)
      if (level === stack.length) {
        const parentArray = stack[level - 1]
        const parent = parentArray[parentArray.length - 1]
        parent.children = []
        stack.push(parent.children)
      } else {
        stack.length = level + 1
      }
      stack[level].push({ text: item[2].trim(), children: undefined })
      continue
    }
    if (list !== undefined) flush()
    paragraph.push(trimmed)
  }
  flush()
  return { blocks: out, definitions }
}

/**
 * Render one list, its items on their own lines and any nested list indented no further than a newline.
 * @param {readonly object[]} items - the items at this level.
 * @param {ReadonlyMap<string, string>} definitions - the labels in force.
 * @returns {string} the `<ul>` element.
 */
function renderList(items, definitions) {
  const rendered = items.map((item) => {
    if (item.children === undefined) return `<li>${renderInline(item.text, definitions)}</li>`
    return `<li>${renderInline(item.text, definitions)}\n${renderList(item.children, definitions)}\n</li>`
  })
  return ['<ul>', ...rendered, '</ul>'].join('\n')
}

/**
 * Render parsed blocks to HTML.
 * @param {readonly object[]} parsed - the document's blocks.
 * @param {ReadonlyMap<string, string>} [definitions] - the labels in force, for reference links.
 * @returns {string} the HTML, with a trailing newline unless the document holds no block.
 */
export function render(parsed, definitions = new Map()) {
  const rendered = parsed.map((block) => {
    if (block.kind === 'heading') return `<h${block.level}>${renderInline(block.text, definitions)}</h${block.level}>`
    if (block.kind === 'paragraph') return `<p>${block.lines.map(text => renderInline(text, definitions)).join('\n')}</p>`
    if (block.kind === 'list') return renderList(block.items, definitions)
    const open = block.info === '' ? '<pre><code>' : `<pre><code class="language-${escapeText(block.info)}">`
    return `${open}${block.content.map(text => `${escapeText(text)}\n`).join('')}</code></pre>`
  })
  return rendered.length === 0 ? '' : `${rendered.join('\n')}\n`
}

/**
 * The headings of parsed blocks, for the outline.
 * @param {readonly object[]} parsed - the document's blocks.
 * @returns {{level: number, text: string}[]} the headings in document order.
 */
export function headings(parsed) {
  return parsed.filter(block => block.kind === 'heading').map(block => ({ level: block.level, text: block.text }))
}
"}

