/** The command: `html`, `outline`, and `defs`, each over the document on standard input and an optional definitions file. */

import { readFileSync } from 'node:fs'
import { BlockError, headings, parse, render, splitLines } from './block.js'
import { DefsError, parseDefinitions } from './defs.js'

const USAGE = 'usage: cli.js html|outline|defs [<definitions>]'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

const argv = process.argv.slice(2)
const mode = argv[0]
const defsPath = argv[1]
if (!['html', 'outline', 'defs'].includes(mode) || argv.length < 1 || argv.length > 2) fail(USAGE)

let fileDefinitions = new Map()
if (defsPath !== undefined) {
  let text
  try {
    text = readFileSync(defsPath, 'utf8')
  } catch {
    fail(`cannot read definitions ${defsPath}`)
  }
  try {
    fileDefinitions = parseDefinitions(text)
  } catch (error) {
    if (!(error instanceof DefsError)) throw error
    fail(`${defsPath}: line ${error.line}: ${error.message}`)
  }
}

let blocks
let definitions
try {
  ;({ blocks, definitions } = parse(splitLines(readFileSync(0, 'utf8')), fileDefinitions))
} catch (error) {
  if (!(error instanceof BlockError)) throw error
  fail(`line ${error.line}: ${error.message}`)
}

if (mode === 'html') {
  process.stdout.write(render(blocks, definitions))
} else if (mode === 'outline') {
  process.stdout.write(headings(blocks).map(one => `${one.level} ${one.text}\n`).join(''))
} else {
  const entries = [...definitions.entries()].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
  const lines = entries.map(([label, url]) => `${label} ${url} ${fileDefinitions.has(label) ? 'file' : 'document'}\n`)
  process.stdout.write(`${lines.join('')}total ${entries.length}\n`)
}
"}

